import { StoreError } from './portfolioStore';

export function getStorageProviderStatus(): 'supabase' | 'repository_static' {
  return process.env.SUPABASE_URL && process.env.SUPABASE_SERVICE_ROLE_KEY ? 'supabase' : 'repository_static';
}

// Keys are generated by the server. The submitted filename is display metadata only.
export async function uploadAssetToStorage(
  buffer: Buffer, key: string, type: 'resume' | 'photo', mime: string,
): Promise<string | undefined> {
  const url = process.env.SUPABASE_URL?.replace(/\/$/, '');
  const role = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url && !role) return undefined;
  if (!url || !role) throw new StoreError(503, 'Asset storage configuration is incomplete.');
  const bucket = encodeURIComponent(process.env.SUPABASE_STORAGE_BUCKET || (type === 'photo' ? 'photos' : 'resumes'));
  const object = bucket + '/' + encodeURIComponent(key);
  try {
    const response = await fetch(url + '/storage/v1/object/' + object, {
      method: 'POST',
      headers: { Authorization: `Bearer ${role}`, apikey: role, 'Content-Type': mime },
      body: new Uint8Array(buffer),
      signal: AbortSignal.timeout(10000),
    });
    if (!response.ok) throw new Error();
    return url + '/storage/v1/object/public/' + object;
  } catch {
    throw new StoreError(503, 'Asset storage is unavailable.');
  }
}
